const {chromium}=require('playwright'),{pathToFileURL}=require('url'),path=require('path'),fs=require('fs');
(async()=>{const b=await chromium.launch({args:['--no-sandbox']});try{
const p=await b.newPage({viewport:{width:390,height:1000}}),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.addInitScript(require('./island-test-helper.cjs'));await p.goto(process.env.ART_SITE_URL||pathToFileURL(path.resolve('index.html')).href);await p.click('#learningTab');await p.evaluate(()=>DEUTSCH_JOURNEY.select(0));
if(!await p.locator('#learningView.compact-island').count())throw Error('First island not compact');
if(await p.locator('.expedition-invitation').count())throw Error('Repeated invitation');
if(await p.locator('.compact-details').count()!==4)throw Error('Missing collapsed map collections');
for(const width of [320,390,768,1280]){await p.setViewportSize({width,height:1000});if(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1))throw Error('Overflow '+width);await p.evaluate(()=>{const board=document.querySelector('.expedition-board').getBoundingClientRect(),number=document.querySelector('[data-route-lesson] .expedition-pin-number').getBoundingClientRect();if(number.top<board.top)throw Error('Ship number clipped');const pins=[...document.querySelectorAll('.expedition-pin')];for(let i=0;i<pins.length;i++){const a=pins[i].getBoundingClientRect();for(let k=i+1;k<pins.length;k++){const c=pins[k].getBoundingClientRect();if(a.left<c.right&&a.right>c.left&&a.top<c.bottom&&a.bottom>c.top)throw Error('Pins overlap '+i+':'+k)}}});}
fs.mkdirSync('audit-screenshots',{recursive:true});await p.setViewportSize({width:390,height:1000});await p.screenshot({path:'audit-screenshots/compact-island1-map.png',fullPage:true});
for(const index of ['greetings',0,1,2,3,4,5,6,7]){await p.evaluate(index=>DEUTSCH_JOURNEY.open(index),index);if(!await p.locator('.al-study-grid').count())throw Error('Missing cards '+index);if(!await p.locator('#learningView').evaluate(e=>[...e.querySelectorAll('p')].some(p=>p.textContent.startsWith('Тренування:')&&!p.closest('details'))))throw Error('Training explanation is hidden '+index);if(index!=='greetings'&&!await p.locator('.journey-goal').evaluate(e=>!e.closest('details')&&e.getBoundingClientRect().height>0))throw Error('Lesson goal hidden '+index);if(!await p.locator('[data-lesson-theory]').evaluate(e=>!e.closest('details')&&e.getBoundingClientRect().height>0))throw Error('Theory hidden '+index);if(index!=='greetings'&&!await p.evaluate(()=>{const s=DEUTSCH_ADAPTIVE.snapshot(),st=DEUTSCH_ADAPTIVE.stages.find(st=>st.id===s.stageId);return document.querySelector('[data-lesson-theory]').textContent.includes(st.rule[document.documentElement.lang.startsWith('en')?1:0])}))throw Error('Theory text shortened '+index);const train=p.locator('#alContinue,#greetingBegin');if(!((await train.innerText()).includes('30')))throw Error('Wrong training label '+index);if(index===0)await p.screenshot({path:'audit-screenshots/compact-island1-lesson.png',fullPage:true});}
await p.evaluate(()=>{window.speak=()=>Promise.resolve();DEUTSCH_JOURNEY.open(0);document.querySelector('#alContinue').click();finishTrainingToTest();const a=DEUTSCH_ADAPTIVE;while(!a.snapshot().finished){const q=a.snapshot().queue[a.snapshot().index];a.answer(q.type==='ua'||q.type==='listen'?q.c.ua:q.c.de);document.querySelector('#alNext').click()}});
if(!await p.locator('[data-mastery-new="true"]').count())throw Error('Award missing');await p.screenshot({path:'audit-screenshots/compact-island1-result.png',fullPage:true});await p.click('#alDone');if(!await p.locator('.compact-details[open] .mastery-collection').count())throw Error('New award hidden');
await p.evaluate(()=>DEUTSCH_JOURNEY.select(1));if(!await p.locator('#learningView.compact-island').count()||await p.locator('.mastery-card').count()!==7)throw Error('Village compact collection missing');await p.evaluate(()=>DEUTSCH_JOURNEY.open(0));if(!await p.locator('[data-lesson-theory]').isVisible()||!(await p.locator('#alContinue').innerText()).includes('30'))throw Error('Village lesson theory/chooser missing');
if(errors.length)throw Error(errors.join(';'));console.log('PASS compact island one: responsive pins, all nine intros, training/test reward, new award expanded, second-island compact theory and chooser');
}finally{await b.close()}})().catch(e=>{console.error(e);process.exit(1)});
